/*!
 * Yozora extension for seanime — Iwara (onlinestream-provider)
 *
 * 18+ content. Ported from Yozora's verified live adapter (2026-11, keyless
 * guest access):
 *  - GET https://api.iwara.tv/video/{id} → full object incl. `fileUrl`
 *  - fileUrl answers a JSON array of quality variants
 *    [{id, name:"360", src:{view:"//asta.iwara.tv/view?…&expires=…"}}] —
 *    the playable URL is https: + the src.view of the best variant.
 *  - Thumbnails: https://files.iwara.tv/image/thumbnail/{file.id}/thumbnail-{NN}.jpg
 *  - The guest (keyless) API ignores the `search` param — text search is NOT
 *    faked; searching throws with an actionable message. Explicit-rated
 *    videos need a platform account upstream; a guest sees what Iwara serves
 *    guests.
 *  - No login, DRM or paywall bypassed — these are the platform's own signed
 *    direct files.
 *
 * Seanime contract: global `class Provider` with search / findEpisodes /
 * findEpisodeServer / getSettings.
 */

const BASE = "https://api.iwara.tv"
const SITE = "https://www.iwara.tv"
const BROWSER_UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"

// Iwara's API/CDN requires a browser-like UA plus Referer/Origin — plain
// server UAs get Cloudflare 403 (verified in Yozora's adapter).
async function getJson(url: string): Promise<any> {
  // YOZORA (fork): bound each request to 8s and retry once so one transient
  // upstream stall cannot zero out metadata or streaming resolution.
  let lastErr: unknown = null
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(url, {
        headers: {
          "User-Agent": BROWSER_UA,
          Referer: SITE + "/",
          Origin: SITE,
          Accept: "application/json",
        },
        timeout: 8000,
      })
      if (res.status === 403 || res.status === 503 || res.status === 429) {
        throw ("iwara: upstream answered HTTP " + res.status + " (edge challenge) — try again shortly")
      }
      if (res.status >= 400) {
        throw ("iwara: upstream answered HTTP " + res.status)
      }
      return JSON.parse(res.text())
    } catch (e) {
      lastErr = e
    }
  }
  throw lastErr
}

function numericQuality(name: string): number {
  const n = parseInt(name || "0", 10)
  return isNaN(n) ? 0 : n
}

function absolute(url: string): string {
  if (url.indexOf("//") === 0) return "https:" + url
  return url
}

// YOZORA (fork): the Go server hands findEpisodes the entry's tagged site URL
// (e.g. "https://www.iwara.tv/video/HuHJvTLZezb0cc"); the API needs the bare id.
// Bare ids pass through unchanged.
function iwaraVideoIdFrom(x: unknown): string {
  const s = String(x)
  const m = s.match(/iwara\.tv\/video\/([A-Za-z0-9_-]+)/)
  return m ? m[1] : s
}

interface IwVideo {
  id: string
  title: string
  fileUrl?: string | null
  file?: { id?: string }
  thumbnail?: number
}

function toSearchResult(v: any): any {
  const fid = v.file && v.file.id ? String(v.file.id) : null
  return {
    id: String(v.id),
    title: String(v.title || v.id),
    year: v.createdAt ? new Date(v.createdAt).getUTCFullYear() : null,
    image: fid ? "https://files.iwara.tv/image/thumbnail/" + fid + "/thumbnail-01.jpg" : undefined,
    imageHeaders: { Referer: SITE + "/" },
  }
}

class Provider {
  async search(opts: { query: string; dub: boolean; year: number }): Promise<any[]> {
    const raw = opts && opts.query ? String(opts.query) : ""
    const tags: string[] = []
    let sort = ""
    const parts = raw.trim().split(/\s+/)
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i]
      if (part.indexOf("tag:") === 0 && part.length > 4) tags.push(part.slice(4))
      else if (part.indexOf("sort:") === 0 && part.length > 5) {
        const s = part.slice(5)
        if (["trending", "date", "views", "likes"].indexOf(s) >= 0) sort = s
      }
    }
    let url = BASE + "/videos?limit=24"
    const sortOnly = raw.trim() !== "" && tags.length === 0 && parts.every((x: string) => x.indexOf("sort:") === 0)
    if (tags.length) {
      // REAL upstream tag filtering works keylessly (verified 2026-11).
      url += "&tags=" + encodeURIComponent(tags.join(","))
      if (sort) url += "&sort=" + sort
    } else if (!raw.trim() || sortOnly) {
      url += "&sort=" + (sort || "trending")
    } else {
      // VERIFIED (2026-11): the guest API ignores the `search` param —
      // free-text would silently return unrelated results.
      throw (
        "iwara: free-text search needs an Iwara account upstream — use tag:hmv (real tag filter), sort:trending, or paste an https://www.iwara.tv/video/{id} URL",
      )
    }
    const j = await getJson(url)
    const list = (j && j.results) || []
    if (!list.length) throw ("iwara: no videos returned" + (tags.length ? " for tag '" + tags.join(",") + "' (tags are lowercase upstream, e.g. hmv, dance)" : ""))
    const out: any[] = []
    for (let i = 0; i < list.length; i++) out.push(toSearchResult(list[i]))
    return out
  }

  async findEpisodes(id: string): Promise<any[]> {
    // YOZORA (fork): id may be the tagged site URL — normalize to the bare id.
    const vid = iwaraVideoIdFrom(id)
    const v: IwVideo = await getJson(BASE + "/video/" + encodeURIComponent(vid))
    if (!v || !v.id) throw ("iwara: video " + vid + " not found")
    return [
      {
        id: v.id,
        number: 1,
        url: SITE + "/video/" + v.id,
        title: v.title || vid,
      },
    ]
  }

  async findEpisodeServer(episode: any, server: string): Promise<any> {
    // YOZORA (fork): normalize in case episode.id is a site URL.
    const id = iwaraVideoIdFrom(episode && episode.id ? String(episode.id) : "")
    if (!id) throw ("iwara: episode has no id")
    const v: IwVideo = await getJson(BASE + "/video/" + encodeURIComponent(id))
    if (!v || !v.fileUrl) throw ("iwara: no signed fileUrl returned for this video")

    // fileUrl → JSON array of quality variants
    const variants = await getJson(absolute(v.fileUrl))
    if (!variants || !variants.length) {
      throw ("iwara: fileUrl returned no stream variants")
    }
    let best: any = null
    for (const variant of variants) {
      if (!best || numericQuality(variant && variant.name) > numericQuality(best.name)) {
        best = variant
      }
    }
    const view = best && best.src ? best.src.view || best.src.download : null
    if (!view) throw ("iwara: no view/download URL in stream variants")

    const headers: Record<string, string> = {
      "User-Agent": BROWSER_UA,
      Referer: SITE + "/",
    }
    const sources: any[] = [
      {
        url: absolute(view),
        type: "mp4",
        quality: best && best.name ? best.name + "p" : "default",
        subtitles: [],
      },
    ]
    // Lower variants as fallback qualities
    for (const variant of variants) {
      if (!variant || !variant.src || variant === best) continue
      const vUrl = variant.src.view || variant.src.download
      if (!vUrl) continue
      sources.push({
        url: absolute(vUrl),
        type: "mp4",
        quality: variant.name ? variant.name + "p" : "alt",
        subtitles: [],
      })
    }
    return { server: "default", headers: headers, videoSources: sources }
  }

  getSettings(): any {
    return { episodeServers: ["default"], supportsDub: false }
  }
}
